import{_ as t,o as s,c as o,ag as i}from"./chunks/framework.7He2WLS4.js";const g=JSON.parse('{"title":"Common Issues","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/common-issues.md","filePath":"troubleshooting/common-issues.md","lastUpdated":1772297611000}'),a={name:"troubleshooting/common-issues.md"};function n(r,e,h,l,p,c){return s(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h1><p>This page covers the most frequently encountered issues when using NectoProxy, along with their causes and solutions.</p><h2 id="no-traffic-appearing-in-the-web-ui" tabindex="-1">No Traffic Appearing in the Web UI <a class="header-anchor" href="#no-traffic-appearing-in-the-web-ui" aria-label="Permalink to &quot;No Traffic Appearing in the Web UI&quot;">​</a></h2><p><strong>Symptom:</strong> NectoProxy is running and the Web UI loads, but no traffic entries appear when you browse.</p><h3 id="possible-causes-and-solutions" tabindex="-1">Possible Causes and Solutions <a class="header-anchor" href="#possible-causes-and-solutions" aria-label="Permalink to &quot;Possible Causes and Solutions&quot;">​</a></h3><p><strong>1. Browser is not configured to use the proxy</strong></p><p>The most common cause. Verify your browser&#39;s proxy settings point to <code>localhost:8888</code>.</p><details class="details custom-block"><summary>How to Check Proxy Settings by Browser</summary><p><strong>Chrome / Edge (uses system proxy on macOS/Windows):</strong></p><ul><li>macOS: System Preferences &gt; Network &gt; Advanced &gt; Proxies</li><li>Windows: Settings &gt; Network &amp; Internet &gt; Proxy</li><li>Linux: Settings &gt; Network &gt; Network Proxy</li></ul><p><strong>Firefox (has its own proxy settings):</strong></p><ul><li>Preferences &gt; General &gt; Network Settings &gt; Settings</li><li>Set Manual proxy: HTTP Proxy <code>127.0.0.1</code>, Port <code>8888</code></li><li>Check &quot;Also use this proxy for HTTPS&quot;</li></ul><p><strong>Using environment variables (for CLI tools):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HTTP_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://localhost:8888</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HTTPS_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://localhost:8888</span></span></code></pre></div></details><p><strong>2. Wrong port</strong></p><p>Double-check that the port in your proxy settings matches the port NectoProxy is listening on. The default is <code>8888</code>, but if you started with <code>-p 9999</code>, use that port instead.</p><p><strong>3. Recording is paused</strong></p><p>Check the header of the Web UI. If the recording button shows a <strong>play icon</strong> instead of a <strong>pause icon</strong>, recording is paused. Click it to resume recording. Traffic still flows through the proxy when paused, but entries are not captured or displayed.</p><p><strong>4. Different session is selected</strong></p><p>Traffic is recorded into the active session. If you switched sessions, the traffic list shows entries from the currently selected session. Make sure you are viewing the correct session.</p><hr><h2 id="https-sites-show-security-errors" tabindex="-1">HTTPS Sites Show Security Errors <a class="header-anchor" href="#https-sites-show-security-errors" aria-label="Permalink to &quot;HTTPS Sites Show Security Errors&quot;">​</a></h2><p><strong>Symptom:</strong> HTTP sites work fine through the proxy, but HTTPS sites display security warnings like &quot;Your connection is not private&quot; or <code>NET::ERR_CERT_AUTHORITY_INVALID</code>.</p><p><strong>Cause:</strong> The NectoProxy CA certificate is not installed or not trusted on your system.</p><p><strong>Solution:</strong> Install the CA certificate. See the detailed <a href="./certificate-errors.html">Certificate Errors</a> page for platform-specific instructions.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Show installation instructions</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install</span></span></code></pre></div><hr><h2 id="rules-not-being-applied" tabindex="-1">Rules Not Being Applied <a class="header-anchor" href="#rules-not-being-applied" aria-label="Permalink to &quot;Rules Not Being Applied&quot;">​</a></h2><p><strong>Symptom:</strong> You created a rule, but requests matching the pattern are not affected.</p><h3 id="check-these-things" tabindex="-1">Check These Things <a class="header-anchor" href="#check-these-things" aria-label="Permalink to &quot;Check These Things&quot;">​</a></h3><p><strong>1. Is the rule enabled?</strong></p><p>In the Rules panel, verify the toggle next to your rule is turned on (enabled). Disabled rules are ignored during evaluation.</p><p><strong>2. Does the match pattern actually match?</strong></p><p>Rule matching is based on the URL, method, host, path, and headers. Common mistakes:</p><table tabindex="0"><thead><tr><th>Problem</th><th>Example</th><th>Fix</th></tr></thead><tbody><tr><td>Missing wildcard</td><td><code>/api/users</code> does not match <code>https://example.com/api/users</code></td><td>Use <code>*/api/users</code></td></tr><tr><td>Wrong method</td><td>Rule matches GET but request is POST</td><td>Add the correct method</td></tr><tr><td>Case sensitivity</td><td><code>/API/Users</code> does not match <code>/api/users</code></td><td>Match the exact case</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Test your match pattern by looking at the URL in the traffic list. Copy the full URL and compare it against your rule&#39;s match pattern.</p></div><p><strong>3. Check rule priority</strong></p><p>If multiple rules match the same request, the rule with the highest priority number is applied first. A lower-priority rule might be getting overridden.</p><p><strong>4. Is there a conflicting rule?</strong></p><p>A Block rule with higher priority could be preventing your Mock rule from firing. Review all active rules for conflicts.</p><hr><h2 id="websocket-connections-failing" tabindex="-1">WebSocket Connections Failing <a class="header-anchor" href="#websocket-connections-failing" aria-label="Permalink to &quot;WebSocket Connections Failing&quot;">​</a></h2><p><strong>Symptom:</strong> WebSocket connections fail when going through the proxy, but work fine without the proxy.</p><p><strong>Solutions:</strong></p><ol><li><p><strong>Ensure WebSocket traffic goes through the proxy port (8888).</strong> WebSocket connections start as HTTP upgrade requests and must use the proxy port, not the UI port.</p></li><li><p><strong>Check for SSL passthrough.</strong> If the WebSocket server&#39;s domain is in the SSL passthrough list, NectoProxy will not intercept the connection. This is usually correct, but it means you will not see frames in the UI.</p></li><li><p><strong>Check for certificate pinning.</strong> Some WebSocket libraries or servers implement certificate pinning. If the library validates certificates strictly, it will reject NectoProxy&#39;s generated certificates. Add the domain to SSL passthrough as a workaround.</p></li></ol><hr><h2 id="binary-body-shows-garbled-text" tabindex="-1">Binary Body Shows Garbled Text <a class="header-anchor" href="#binary-body-shows-garbled-text" aria-label="Permalink to &quot;Binary Body Shows Garbled Text&quot;">​</a></h2><p><strong>Symptom:</strong> Opening a traffic entry for an image, video, or binary file shows garbled characters in the body viewer.</p><p><strong>Explanation:</strong> This is expected behavior. Binary content (images, PDF, protobuf, compressed data) is stored as-is in the database and displayed as base64-encoded text in the UI. NectoProxy does not attempt to render binary content inline.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Check the <code>Content-Type</code> header to identify the content type. Common binary types include <code>image/png</code>, <code>application/octet-stream</code>, <code>application/pdf</code>, and <code>application/protobuf</code>.</p></div><hr><h2 id="large-requests-are-truncated" tabindex="-1">Large Requests Are Truncated <a class="header-anchor" href="#large-requests-are-truncated" aria-label="Permalink to &quot;Large Requests Are Truncated&quot;">​</a></h2><p><strong>Symptom:</strong> The request or response body appears to be cut off, or the entry has an <code>isTruncated</code> flag.</p><p><strong>Cause:</strong> The body exceeded the <code>maxBodySize</code> limit (default 10 MB). NectoProxy captures only the first <code>maxBodySize</code> bytes to prevent excessive memory usage.</p><p><strong>Solution:</strong> Increase the <code>maxBodySize</code> setting:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Increase to 50 MB</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8889/api/settings/maxBodySize</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;value&quot;: 52428800}&#39;</span></span></code></pre></div><p>Or update it in the Settings panel in the Web UI.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Increasing <code>maxBodySize</code> significantly will increase memory usage and database size. Only increase it when you specifically need to capture large bodies.</p></div><hr><h2 id="address-already-in-use-error-eaddrinuse" tabindex="-1">&quot;Address Already in Use&quot; Error (EADDRINUSE) <a class="header-anchor" href="#address-already-in-use-error-eaddrinuse" aria-label="Permalink to &quot;&quot;Address Already in Use&quot; Error (EADDRINUSE)&quot;">​</a></h2><p><strong>Symptom:</strong> NectoProxy fails to start with an error like <code>Port is already in use</code>.</p><p><strong>Cause:</strong> Another process is already listening on port 8888 or 8889.</p><p><strong>Solutions:</strong></p><ol><li><p><strong>Use a different port:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9999</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9998</span></span></code></pre></div></li><li><p><strong>Find and stop the conflicting process:</strong> See the <a href="./port-conflicts.html">Port Conflicts</a> page for details.</p></li></ol><hr><h2 id="cannot-connect-from-other-devices" tabindex="-1">Cannot Connect from Other Devices <a class="header-anchor" href="#cannot-connect-from-other-devices" aria-label="Permalink to &quot;Cannot Connect from Other Devices&quot;">​</a></h2><p><strong>Symptom:</strong> NectoProxy works on your local machine, but phones or other computers on the network cannot connect.</p><p><strong>Causes and Solutions:</strong></p><p><strong>1. NectoProxy is bound to localhost only</strong></p><p>By default, NectoProxy binds to <code>127.0.0.1</code>, which only accepts connections from the local machine. Start with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span></span></code></pre></div><p><strong>2. Firewall is blocking the port</strong></p><p>Check your system&#39;s firewall and ensure ports 8888 and 8889 are open for inbound connections.</p><p><strong>3. Devices are on different networks</strong></p><p>Your computer and the connecting device must be on the same network (e.g., the same Wi-Fi network).</p><p><strong>4. Using the wrong IP address</strong></p><p>Check the Settings panel in the Web UI for your computer&#39;s IP address. Use that address in the connecting device&#39;s proxy settings, not <code>localhost</code> or <code>127.0.0.1</code>.</p><hr><h2 id="nectoproxy-crashes-on-startup" tabindex="-1">NectoProxy Crashes on Startup <a class="header-anchor" href="#nectoproxy-crashes-on-startup" aria-label="Permalink to &quot;NectoProxy Crashes on Startup&quot;">​</a></h2><p><strong>Symptom:</strong> NectoProxy exits immediately after starting.</p><p><strong>Possible Causes:</strong></p><table tabindex="0"><thead><tr><th>Cause</th><th>Solution</th></tr></thead><tbody><tr><td>Node.js version too old</td><td>NectoProxy requires Node.js 20+. Check with <code>node -v</code>.</td></tr><tr><td>Corrupted database</td><td>Rename or delete <code>~/.nectoproxy/data.db</code> and restart.</td></tr><tr><td>Port conflict</td><td>Try different ports: <code>nectoproxy start -p 9999 -u 9998</code></td></tr><tr><td>Missing dependencies</td><td>Reinstall: <code>npm install -g nectoproxy</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Run NectoProxy with the <code>DEBUG</code> environment variable for more verbose output:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEBUG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">*</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div></div>`,77)])])}const u=t(a,[["render",n]]);export{g as __pageData,u as default};
